llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Linezolid, the closest analogue (Morgan 0.4507), has essentially complete absolute oral bioavailability (~100%) in patients, directly supporting high F for the shared oxazolidinone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Delpazolid, a close oxazolidinone analogue, has absolute oral bioavailability of 99.75% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Contezolid, another oxazolidinone analogue, has F = 0.64 in healthy subjects, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "YH4808, a thiomorpholine-containing oxazolidinone analogue, has low absolute bioavailability of 10.1%, providing a contradictory example; however, the query's morpholinone is closer to linezolid's morpholine than to thiomorpholine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "Cadazolid, a poorly absorbed oxazolidinone designed for local gastrointestinal action, has very low F, but its low transferability limits its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High is better supported: the closest analogue linezolid and other oxazolidinones (delpazolid, contezolid) show F ≥ 20%, often near 100%; the main low-F analogue YH4808 differs at the thiomorpholine position and is outweighed by the closer linezolid evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule.",
    "The effect of the morpholin-3-one and 5-chlorothiophene carboxamide modifications on first-pass metabolism is not directly covered by the retrieved analogues.",
    "YH4808's low F may be specific to thiomorpholine metabolism, which is not present in the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

